discrete OrganicWasteProcessingSystem
port:
    event input real ReceiveOrganicWaste;
    event output real SendOrganicWaste;
state:
    initial state InitialState
        when entry() then
            statehold(5);
        end;
        when receive(ReceiveOrganicWaste) then
            transition(WasteDetected);
        end;
    end;

    state WasteDetected
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(PreprocessingComplete);
        end;
    end;

    state PreprocessingComplete
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(InitialSend);
        out
            send(SendOrganicWaste, 1);
        end;
    end;

    state InitialSend
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(InitialState);
        end;
    end;
end;
end;

discrete BioConversionSystem
port:
    event input real ReceiveOrganicWaste;
    event output real SendBiogas;
state:
    initial state InitialState
        when entry() then
            statehold(5);
        end;
        when receive(ReceiveOrganicWaste) then
            transition(WasteReceived);
        end;
    end;

    state WasteReceived
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(DigestionComplete);
        end;
    end;

    state DigestionComplete
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(GasCollected);
        end;
    end;

    state GasCollected
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(InitialState);
        out
            send(SendBiogas, 1);
        end;
    end;
end;
end;

discrete EnergyConversionSystem
port:
    event input real ReceiveBiogas;
    event output real SendEnergy;
state:
    initial state InitialState
        when entry() then
            statehold(5);
        end;
        when receive(ReceiveBiogas) then
            transition(BiogasDetected);
        end;
    end;

    state BiogasDetected
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(EnergyConversionComplete);
        end;
    end;

    state EnergyConversionComplete
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(StorageFull);
        end;
    end;

    state StorageFull
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(InitialState);
        out
            send(SendEnergy, 1);
        end;
    end;
end;
end;

discrete PowerDistributionSystem
port:
    event input real ReceiveEnergy;
    event output real SendPower;
state:
    initial state InitialState
        when entry() then
            statehold(5);
        end;
        when receive(ReceiveEnergy) then
            transition(EnergyReceived);
        end;
    end;

    state EnergyReceived
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(PowerDispatched);
        end;
    end;

    state PowerDispatched
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(InitialState);
        out
            send(SendPower, 1);
        end;
    end;
end;
end;

